import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { 
  User, 
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword, 
  signOut, 
  onAuthStateChanged,
  sendPasswordResetEmail 
} from 'firebase/auth';
import { auth } from '../config/firebase';

interface AuthContextType {
  currentUser: User | null;
  login: (email: string) => Promise<void>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  loading: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

interface AuthProviderProps {
  children: ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  async function login(email: string) {
    try {
      // Generate a secure temporary password
      const tempPassword = `temp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      try {
        // First try to sign in with existing account
        await signInWithEmailAndPassword(auth, email, tempPassword);
      } catch (error: any) {
        if (error.code === 'auth/user-not-found') {
          // User doesn't exist, create a new account
          await createUserWithEmailAndPassword(auth, email, tempPassword);
          console.log('New user account created successfully');
        } else if (error.code === 'auth/wrong-password') {
          // User exists but wrong password, try to create new account
          // This handles the case where user was created before but password changed
          try {
            await createUserWithEmailAndPassword(auth, email, tempPassword);
            console.log('User account recreated successfully');
          } catch (createError: any) {
            if (createError.code === 'auth/email-already-in-use') {
              // This shouldn't happen, but just in case
              throw new Error('Account exists but cannot be accessed. Please contact support.');
            }
            throw createError;
          }
        } else {
          throw error;
        }
      }
    } catch (error: any) {
      console.error('Authentication error:', error);
      if (error.code === 'auth/email-already-in-use') {
        throw new Error('This email is already registered. Please try signing in again.');
      } else if (error.code === 'auth/weak-password') {
        throw new Error('Password is too weak. Please try again.');
      } else {
        throw new Error('Authentication failed. Please try again.');
      }
    }
  }

  async function logout() {
    return signOut(auth);
  }

  async function resetPassword(email: string) {
    return sendPasswordResetEmail(auth, email);
  }

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    login,
    logout,
    resetPassword,
    loading
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}
